187	//! \brief Build an AudioData from raw encoded audio bytes (wav / mp3 / flac).
188	//! Decodes via vendored miniaudio (16 kHz mono FP32) and hands raw PCM off to
189	//! the runner; mel extraction happens inside the audio runner per its
190	//! ``audio/config.json``.
191	audioUtils::AudioData loadAudioBufferFromBytes(py::bytes data)
192	{
193	    constexpr int32_t kTargetSampleRate = 16000;
194	    std::string dataStr = data;
195	    audioUtils::AudioData audio;
196	    if (!audioUtils::loadAudioDataFromBytes(
197	            reinterpret_cast<uint8_t const*>(dataStr.data()), dataStr.size(), kTargetSampleRate, audio))
198	    {
199	        throw std::runtime_error("Audio decode failed (unsupported container or corrupt bytes)");
200	    }
201	    return audio;
202	}
203	
204	//! \brief Decode audio bytes + extract mel to numpy.float32 (host-resident).
205	//! Diagnostic helper exposing the C++ ``MelExtractor`` output directly — the
206	//! production path (``loadAudioBufferFromBytes`` -> runner) only returns PCM
207	//! at the Python boundary and runs mel extraction inside the audio runner.
208	//! Returns the FE's natural 2-D layout.
209	py::array_t<float> extractMelToNumpy(py::bytes data, std::string const& feType)
210	{
211	    audio::MelExtractor extractor = audio::makeExtractorByName(feType);
212	    int32_t const targetSampleRate = extractor.config().sampleRate;
213	
214	    char const* rawPtr = nullptr;
215	    Py_ssize_t rawSize = 0;
216	    if (PyBytes_AsStringAndSize(data.ptr(), const_cast<char**>(&rawPtr), &rawSize) != 0)
217	    {
218	        throw py::error_already_set();
219	    }
220	
221	    audio::AudioPCM pcm;
222	    if (!audio::loadAudioBytes(
223	            reinterpret_cast<uint8_t const*>(rawPtr), static_cast<size_t>(rawSize), targetSampleRate, pcm))
224	    {
225	        throw std::runtime_error("Audio decode failed (unsupported container or corrupt bytes)");
226	    }
227	
228	    Tensor hostMel;
229	    if (!extractor.extract(pcm, hostMel))
230	    {
231	        throw std::runtime_error("Mel extraction failed");
232	    }
233	
234	    Coords const& shape = hostMel.getShape();
235	    std::vector<ssize_t> npShape;
236	    npShape.reserve(static_cast<size_t>(shape.getNumDims()));
237	    for (int32_t d = 0; d < shape.getNumDims(); ++d)
238	    {
239	        npShape.push_back(static_cast<ssize_t>(shape[d]));
240	    }
241	    py::array_t<float> out(npShape);
242	    std::memcpy(out.mutable_data(), hostMel.dataPointer<float>(), static_cast<size_t>(shape.volume()) * sizeof(float));
243	    return out;
244	}
