246	//! Build an ImageData (video frame stack) from a (T, H, W, 3) uint8 numpy array. forcecast makes a contiguous
247	//! uint8 copy if needed, so the buffer is always row-major and directly copyable into the device-bound tensor.
248	imageUtils::ImageData loadVideoFromArray(
249	    py::array_t<uint8_t, py::array::c_style | py::array::forcecast> const& array, double fps)
250	{
251	    py::buffer_info info = array.request();
252	    check::check(info.ndim == 4, "video array must be 4D (T, H, W, 3)");
253	    check::check(info.shape[3] == 3, "video array must have 3 channels (last dim == 3)");
254	    check::check(fps > 0.0, "fps must be positive");
255	    int64_t const T = info.shape[0];
256	    int64_t const H = info.shape[1];
257	    int64_t const W = info.shape[2];
258	    int64_t const C = info.shape[3];
259	    check::check(T > 0, "video array must have at least one frame (T > 0)");
260	
261	    rt::Tensor stacked(
262	        {T, H, W, C}, rt::DeviceType::kCPU, nvinfer1::DataType::kUINT8, "pybind::loadVideoFromArray::stacked");
263	    std::memcpy(stacked.dataPointer<unsigned char>(), info.ptr, static_cast<size_t>(T * H * W * C));
264	
265	    imageUtils::ImageData video(std::move(stacked));
266	    video.fps = fps;
267	    return video;
268	}
