565	            for (auto const& messages : batchMessages)
566	            {
567	                LLMGenerationRequest::Request req;
568	                req.messages = messages;
569	                req.logitBias = logitBias;
570	                request.requests.push_back(std::move(req));
571	            }
572	            return request;
573	        },
574	        py::arg("batch_messages"), py::arg("temperature") = 1.0f, py::arg("top_p") = 0.8f, py::arg("top_k") = 50,
575	        py::arg("max_generate_length") = 256, py::arg("apply_chat_template") = true,
576	        py::arg("add_generation_prompt") = true, py::arg("enable_thinking") = false, py::arg("lora_weights_name") = "",
577	        py::arg("save_system_prompt_kv_cache") = false, py::arg("disable_spec_decode") = false,
578	        py::arg("logit_bias") = std::unordered_map<int32_t, float>{}, py::arg("num_logprobs") = 0,
579	        "Create a generation request from a batch of message lists.");
580	}
